(6792016, 1020506, 10785, '<td valign="top">Nice idea and execution. Could you have created a blue background from your seamless white BG? You are lucky to have such willing models, umm I mean daughters!</td>', 'Nice idea and execution. Could you have created a blue background from your seamless white BG? You are lucky to have such willing models, umm I mean daughters!', '2012-06-11 01:15:28.000000', NULL, 1),
(6792028, 1020497, 10785, '<td valign="top">Interesting little abstract/detail of the water and sand.</td>', 'Interesting little abstract/detail of the water and sand.', '2012-06-11 01:22:01.000000', NULL, 1),
(6792035, 1020384, 114285, '<td valign="top">Haha my girl use to do that, apparently strengthens their immune system!</td>', 'Haha my girl use to do that, apparently strengthens their immune system!', '2012-06-11 01:33:14.000000', NULL, 1),
(6792036, 1019969, 114285, '<td valign="top">Gorgeous vintage look, but you spoiled it by adding the big black border, no need to do that.</td>', 'Gorgeous vintage look, but you spoiled it by adding the big black border, no need to do that.', '2012-06-11 01:34:05.000000', NULL, 1),
(6792176, 1020291, 103032, '<td valign="top">Great composition and catch.  Right time, right place. Just a note, I prefer this composition to the other one (your shooting partner I presume) with the same ripples.</td>', 'Great composition and catch.  Right time, right place. Just a note, I prefer this composition to the other one (your shooting partner I presume) with the same ripples.', '2012-06-11 04:17:06.000000', NULL, 1),
(6792180, 1020463, 103032, '<td valign="top">I like the patterns of the sand ripples. This has the abstract quality to it . However, I prefer the composition of you shooting partner''s pic. Best wishes in voting to both of you.</td>', 'I like the patterns of the sand ripples. This has the abstract quality to it . However, I prefer the composition of you shooting partner''s pic. Best wishes in voting to both of you.', '2012-06-11 04:20:07.000000', NULL, 1),
(6792182, 1020063, 101668, '<td valign="top">Seems vaguely familiar! Still a lovely shot. pp just right.</td>', 'Seems vaguely familiar! Still a lovely shot. pp just right.', '2012-06-11 04:20:10.000000', NULL, 1),
(6792187, 1020549, 103032, '<td valign="top">Nice. Reminds me of road trips to the coast...  This image gives me the sense of solitude (solo set of foot prints) even though there are people in the background.  Must say, the more I look at it, the more I like it.</td>', 'Nice. Reminds me of road trips to the coast...  This image gives me the sense of solitude (solo set of foot prints) even though there are people in the background.  Must say, the more I look at it, the more I like it.', '2012-06-11 04:32:25.000000', NULL, 1),
