(6797261, 1020399, 100831, '<td valign="top">Oh to be young again.... I''m not sure which is better, the sentiment or the photograph!</td>', 'Oh to be young again.... I''m not sure which is better, the sentiment or the photograph!', '2012-06-17 23:44:24.000000', NULL, 1),
(6797262, 1020510, 100831, '<td valign="top">Nice.</td>', 'Nice.', '2012-06-17 23:44:35.000000', NULL, 1),
(6797263, 1020394, 138630, '<td valign="top">I just love this one but find myself wishing the distant horizon was straight so I could focus on the lovely foreground and that delightful girl.  I can feel the waves lapping her bare feet.  Great colors and light.  9<br/>eta: Ouch - you are so right.  The horizon is straight.  I had to stand up and look down on the image to see the trees and the real horizon.  Sorry.<br/><br/><i>Message edited by author 2012-06-18 00:05:18.</i></td>', 'I just love this one but find myself wishing the distant horizon was straight so I could focus on the lovely foreground and that delightful girl.  I can feel the waves lapping her bare feet.  Great colors and light.  9eta: Ouch - you are so right.  The horizon is straight.  I had to stand up and look down on the image to see the trees and the real horizon.  Sorry.', '2012-06-17 23:51:41.000000', '2012-06-18 01:05:18.000000', 1),
(6797264, 1020356, 138630, '<td valign="top">So simple but the rich tones and dramatic lines of the gate and shadows are very appealing.  One of my favorites.  9</td>', 'So simple but the rich tones and dramatic lines of the gate and shadows are very appealing.  One of my favorites.  9', '2012-06-17 23:52:20.000000', NULL, 1),
